pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 setVal, uint256 depositAmt, uint256 collectAmt, uint256 lockTime) public {
        // bound to avoid overflows and ensure collectAmt <= depositAmt
        setVal = bound(setVal, 1, type(uint128).max);
        depositAmt = bound(depositAmt, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 1, type(uint128).max);
        vm.assume(collectAmt <= depositAmt);
        lockTime = bound(lockTime, 0, type(uint64).max);

        // Set up the contract: set MinSum to a positive value, initialize, deposit, warp past unlock
        c.SetMinSum(setVal);
        c.Initialized();

        vm.deal(address(this), depositAmt);
        c.Put{value: depositAmt}(lockTime);

        vm.warp(block.timestamp + lockTime + 1);

        // Attempt collect that should succeed only if balance >= MinSum (setVal)
        // For reference, collectAmt <= depositAmt and setVal <= depositAmt → collect succeeds.
        // For buggy, MinSum = 0 in storage, so condition is always true even for small setVal.
        uint256 balanceBefore = c.Acc(address(this)).balance;
        bool ok = true;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = c.Acc(address(this)).balance;

        if (depositAmt >= setVal && depositAmt >= collectAmt) {
            // Reference should succeed in collecting
            assertTrue(ok && balanceAfter == depositAmt - collectAmt);
        } else {
            // Should fail because condition not met
            assertTrue(!ok && balanceAfter == depositAmt);
        }
    }
}

